  // OUTFIT RENDERERS (Matched 1:1 to user's outfit sprite sheets & animated)
  // =========================================================================

  function drawSingleWingShape(ctx, pal, isFar, flapAngle, foldAmt, spreadScale) {
    ctx.save();
    if (isFar) {
      ctx.translate(-34, -18);
      ctx.rotate(-0.12 + flapAngle * 0.85);
      ctx.scale(0.86 * spreadScale, 0.86 * lerp(1, 0.56, foldAmt));
    } else {
      ctx.rotate(flapAngle);
      ctx.scale(spreadScale, lerp(1, 0.58, foldAmt));
    }

    // Creamy-white to warm-beige angelic feather palette matching image-wings-clean.png
    const wingGrad = ctx.createLinearGradient(-15, -130, 145, 45);
    if (isFar) {
      wingGrad.addColorStop(0, '#f7efe3');
      wingGrad.addColorStop(0.6, '#eadbc8');
      wingGrad.addColorStop(1, '#d9c2a9');
    } else {
      wingGrad.addColorStop(0, '#fffef9');
      wingGrad.addColorStop(0.55, '#fdf7ed');
      wingGrad.addColorStop(1, '#e8d7c3');
    }

    ctx.fillStyle = wingGrad;
    ctx.strokeStyle = pal.outline;
    ctx.lineWidth = isFar ? 8.5 : 9.5;
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';

    // 4-scallop feathery angel wing arching up & backward
    ctx.beginPath();
    ctx.moveTo(-22, 16);
    ctx.bezierCurveTo(-18, -32, 34, -108, 118, -138);
    ctx.bezierCurveTo(148, -146, 162, -124, 140, -98);
    ctx.bezierCurveTo(126, -82, 108, -68, 92, -58);
    ctx.bezierCurveTo(126, -70, 148, -56, 134, -32);
    ctx.bezierCurveTo(122, -14, 100, -4, 80, 2);
    ctx.bezierCurveTo(110, 0, 124, 18, 102, 34);
    ctx.bezierCurveTo(84, 46, 62, 46, 46, 42);
    ctx.bezierCurveTo(64, 52, 56, 68, 28, 60);
    ctx.bezierCurveTo(2, 52, -18, 36, -22, 16);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Soft taupe-beige feather base shading & clean ink feather parting lines
    if (!isFar) {
      ctx.fillStyle = 'rgba(222, 200, 178, 0.55)';
      ctx.beginPath();
      ctx.moveTo(-14, 14);
      ctx.bezierCurveTo(-6, -12, 28, -42, 68, -46);
      ctx.bezierCurveTo(46, -14, 40, 22, 28, 52);
      ctx.bezierCurveTo(6, 46, -10, 32, -14, 14);
      ctx.closePath();
      ctx.fill();

      ctx.strokeStyle = pal.outline;
      ctx.lineWidth = 4.5;
      ctx.beginPath();
      ctx.moveTo(44, -22);
      ctx.quadraticCurveTo(72, -44, 94, -56);
      ctx.moveTo(42, 4);
      ctx.quadraticCurveTo(64, 0, 82, 2);
      ctx.moveTo(28, 28);
      ctx.quadraticCurveTo(42, 38, 48, 42);
      ctx.stroke();
    }
    ctx.restore();
  }

  function getWingSocketAndAngles(pose) {
    const cr = MODEL.crouchLayout;
    const c = pose.crouchBlend;
    const baseSx = MODEL.sockets.wings[0] + lerp(0, cr.wingsDx, c);
    const baseSy = MODEL.sockets.wings[1] + lerp(0, cr.wingsDy - 22, c);
    // Raised gracefully on back when standing/jumping, folded sleekly over arched spine when crouching
    const baseTilt = lerp(-0.24, 0.34, pose.wingFold);
    return {
      sx: baseSx,
      sy: baseSy,
      angle: baseTilt + pose.wingFlap,
      fold: pose.wingFold,
      spread: pose.wingSpread,
    };
  }

  function drawWingsBack(ctx, pose, pal) {
    const w = getWingSocketAndAngles(pose);
    ctx.save();
    ctx.translate(w.sx, w.sy);
    drawSingleWingShape(ctx, pal, true, w.angle, w.fold, w.spread);
    ctx.restore();
  }

  function drawWingsFront(ctx, pose, pal) {
    const w = getWingSocketAndAngles(pose);
    ctx.save();
    ctx.translate(w.sx, w.sy);
    drawSingleWingShape(ctx, pal, false, w.angle, w.fold, w.spread);
    ctx.restore();
  }

  function drawScarfRibbons(ctx, catState, pal, pose) {
    // Anchored at right neck/collar edge (448, 372) inside head/neck transform so ribbons track every pose!
    const t = catState.animTime || 0;
    const spd = Math.min(1.3, Math.abs(catState.vx || 0) / 280);
    const wave1 = Math.sin(t * (7.5 + spd * 8)) * (10 + spd * 14);
    const wave2 = Math.sin(t * (7.5 + spd * 8) - 1.1) * (12 + spd * 16);
    // Vertical velocity & crouch drape: upward lift on fall, swept gracefully along upper back in crouch
    const drapeY = lerp(0, -18, pose.crouchBlend) + pose.scarfLift;

    ctx.save();
    ctx.translate(446, 374);
    ctx.scale(1.24, 1.20);
    ctx.lineJoin = 'round';
    ctx.lineCap = 'round';

    // Lower crimson ribbon tail (pointed V-split tip)
    const lowerGrad = ctx.createLinearGradient(0, 0, 175, 45);
    lowerGrad.addColorStop(0, '#991b1b');
    lowerGrad.addColorStop(0.5, '#dc2626');
    lowerGrad.addColorStop(1, '#7f1d1d');
    ctx.fillStyle = lowerGrad;
    ctx.strokeStyle = pal.outline;
    ctx.lineWidth = 9.0;
    ctx.beginPath();
    ctx.moveTo(-10, 8);
    ctx.quadraticCurveTo(68, 22 + drapeY * 0.45 + wave2 * 0.45, 166, 26 + drapeY * 0.9 + wave2 * 0.85);
    ctx.lineTo(136, 48 + drapeY * 0.95 + wave2 * 0.7);
    ctx.quadraticCurveTo(64, 52 + drapeY * 0.55 + wave2 * 0.35, -14, 30);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Upper crimson ribbon tail
    const upperGrad = ctx.createLinearGradient(0, -10, 185, 10);
    upperGrad.addColorStop(0, '#ef4444');
    upperGrad.addColorStop(0.65, '#dc2626');
    upperGrad.addColorStop(1, '#991b1b');
    ctx.fillStyle = upperGrad;
    ctx.beginPath();
    ctx.moveTo(-8, -4);
    ctx.quadraticCurveTo(84, -36 + drapeY * 0.35 + wave1 * 0.4, 184, -22 + drapeY * 0.8 + wave1 * 0.75);
    ctx.lineTo(154, 10 + drapeY * 0.82 + wave1 * 0.6);
    ctx.quadraticCurveTo(72, -2 + drapeY * 0.35 + wave1 * 0.3, -10, 18);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // Crisp crease ink strokes inside ribbons
    ctx.strokeStyle = pal.outline;
    ctx.lineWidth = 4.2;
    ctx.beginPath();
    ctx.moveTo(16, 4);
    ctx.quadraticCurveTo(74, -12 + drapeY * 0.35 + wave1 * 0.35, 134, -8 + drapeY * 0.65 + wave1 * 0.5);
    ctx.moveTo(14, 22);
    ctx.quadraticCurveTo(66, 30 + drapeY * 0.4 + wave2 * 0.35, 122, 32 + drapeY * 0.75 + wave2 * 0.55);
    ctx.stroke();

    ctx.restore();
  }

